async function run() {
  const nowIso = now();
  const from = dates.startOfDay(nowIso, 0);
  const to = dates.addDays(from, 1);

  const events = await calendar.events({ from, to });
  const emails = await gmail.search({ query: "in:inbox is:unread", days: 1, unread: true, max: 20 });
  const weather = await http.getJSON(
    "https://api.open-meteo.com/v1/forecast?latitude=-23.55&longitude=-46.63&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=America%2FSao_Paulo&forecast_days=1"
  );

  const sortedEvents = events.slice().sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

  const agendaLines = sortedEvents.map((ev) => {
    if (ev.start.length === 10) {
      return "• Dia todo: " + ev.title;
    }
    const time = dates.format(ev.start, "HH:mm");
    return "• " + time + " " + ev.title;
  });

  const importantEmails = [];
  for (const m of emails) {
    const j = await judge.important(m);
    if (j.p >= 0.5) importantEmails.push(m);
  }
  const emailLines = importantEmails.map((m) => "• " + (m.from_name || m.from) + ": " + m.subject);

  const tmax = weather && weather.daily ? weather.daily.temperature_2m_max[0] : null;
  const tmin = weather && weather.daily ? weather.daily.temperature_2m_min[0] : null;
  const precip = weather && weather.daily ? weather.daily.precipitation_probability_max[0] : null;

  const weekday = dates.format(nowIso, "EEEE");
  const dayMonth = dates.format(nowIso, "dd/MM");

  let text = "Bom dia! Resumo de " + weekday + ", " + dayMonth + "\n\nAgenda:\n";
  text += agendaLines.length ? agendaLines.join("\n") : "Nenhum compromisso hoje.";
  text += "\n\nEmails importantes:\n";
  text += emailLines.length ? emailLines.join("\n") : "Nenhum email importante.";
  if (tmax !== null && tmin !== null && precip !== null) {
    text +=
      "\n\nTempo em São Paulo: " +
      tmin.toFixed(1) +
      "°C a " +
      tmax.toFixed(1) +
      "°C, " +
      precip +
      "% de chance de chuva.";
  }

  log(text);
  await telegram.send({ text });
}

async function run() {
  const today = dates.today();
  const end = dates.addDays(today, 7);

  const emails = await gmail.search({
    query: "boleto OR fatura OR invoice OR vencimento",
    days: 30,
    max: 30
  });

  const items = [];
  for (const e of emails) {
    const text = e.snippet || "";
    const due = dates.parse(text) || dates.parse(e.subject || "");
    if (!due) continue;
    if (dates.isBefore(due, today)) continue; // já venceu
    if (dates.isBefore(end, due)) continue;    // vence depois da janela de 7 dias

    const amountText = money.find(text) || money.find(e.subject || "");
    if (!amountText) continue;

    items.push({ due, amountText, subject: e.subject, id: e.id });
  }

  if (items.length === 0) {
    log("Nenhuma conta vencendo nos próximos 7 dias.");
    return;
  }

  items.sort((a, b) => (dates.isBefore(a.due, b.due) ? -1 : 1));

  let total = 0;
  const lines = items.map((it) => {
    const value = money.parse(it.amountText);
    if (value) total += value;
    return `• ${dates.format(it.due, "dd/MM")} — ${it.subject}: ${it.amountText}`;
  });

  const text = `Contas vencendo nos próximos 7 dias:\n\n${lines.join("\n")}\n\nTotal: ${money.format(total, "BRL")}`;

  await telegram.send({ text });
}

async function run() {
  const todayIso = dates.today();

  const emails = await gmail.search({
    query: "boleto OR fatura OR invoice OR vencimento",
    days: 30,
    max: 30
  });

  const paidKeywords = [
    'pagamento confirmado',
    'pago',
    'recibo',
    'comprovante',
    'payment confirmed',
    'paid'
  ];

  const bills = [];

  for (const email of emails) {
    const subject = email.subject || '';
    const snippet = email.snippet || '';
    const combinedLower = (subject + ' ' + snippet).toLowerCase();

    if (paidKeywords.some(k => combinedLower.includes(k))) {
      continue;
    }

    const dueDate = dates.parse(snippet + ' ' + subject);
    if (!dueDate) {
      continue;
    }

    const diff = dates.diffDays(todayIso, dueDate);
    if (diff < 0 || diff > 7) {
      continue;
    }

    const amountText = money.find(snippet) || money.find(subject);
    if (!amountText) {
      continue;
    }
    const amountNum = money.parse(amountText);
    if (amountNum === null || amountNum === undefined) {
      continue;
    }

    bills.push({
      dueDate,
      amountText,
      amountNum,
      subject: subject.trim()
    });
  }

  if (bills.length === 0) {
    log('Nenhuma conta em aberto vencendo nos próximos 7 dias.');
    return;
  }

  bills.sort((a, b) => dates.diffDays(b.dueDate, a.dueDate));

  let total = 0;
  const lines = bills.map(b => {
    total += b.amountNum;
    return `• ${dates.format(b.dueDate, 'dd/MM')} — ${b.subject}: ${b.amountText}`;
  });

  const text = `Contas vencendo nos próximos 7 dias:\n\n${lines.join('\n')}\n\nTotal: ${money.format(total, 'BRL')}`;

  await telegram.send({ text });
}

async function run() {
  const items = await gmail.search({ query: "in:inbox is:unread", unread: true, days: 2, max: 50 });

  let archivedCount = 0;
  const archivedNames = [];

  for (const item of items) {
    const { p } = await judge.newsletter(item);
    if (p >= 0.5) {
      await gmail.archive({ id: item.id });
      archivedCount++;
      archivedNames.push(item.from_name || item.from);
      log("Archived: " + item.subject);
    } else {
      log("Kept: " + item.subject);
    }
  }

  let text;
  if (archivedCount === 0) {
    text = "Inbox cleanup: no newsletters or promos to archive today.";
  } else {
    const plural = archivedCount > 1 ? "s" : "";
    let msg = `Inbox cleanup done: archived ${archivedCount} newsletter${plural}/promo${plural}`;
    if (archivedNames.length > 0) {
      msg += ` (${archivedNames.join(", ")})`;
    }
    text = msg + ".";
  }

  await telegram.send({ text });
}

async function run() {
  const NOTIFIED_LABEL = "VigiaAnaNotified";
  const BOSS_EMAIL = "ana@acme.com";

  const emails = await gmail.search({
    query: `from:${BOSS_EMAIL} is:unread in:inbox`,
    unread: true,
    days: 7,
    max: 20
  });

  for (const email of emails) {
    const from = (email.from || "").toLowerCase();
    if (!from.includes(BOSS_EMAIL.toLowerCase())) continue;

    const labels = (email.labels || []).map(l => l.toLowerCase());
    if (labels.includes(NOTIFIED_LABEL.toLowerCase())) continue;

    const name = email.from_name || email.from;
    const subject = email.subject || "(sem assunto)";
    const snippet = email.snippet || "";

    const text = `📩 Email da ${name}: "${subject}"\n${snippet}`.trim();
    await telegram.send({ text });
    await gmail.label({ id: email.id, label: NOTIFIED_LABEL });
    log(`Avisado sobre email de Ana: ${email.id} - ${subject}`);
  }
}

async function run() {
  const start = dates.startOfDay(now(), 1); // tomorrow at midnight
  const end = dates.addDays(start, 7); // exclusive boundary, one week later

  const events = await calendar.events({ from: start, to: end });

  const days = [];
  for (let i = 0; i < 7; i++) {
    const dayDate = dates.addDays(start, i);
    const dayEvents = events
      .filter((e) => dates.sameDay(e.start, dayDate))
      .slice()
      .sort((a, b) => (dates.isBefore(a.start, b.start) ? -1 : 1));
    days.push({ dayDate, dayEvents });
  }

  const blocks = days.map(({ dayDate, dayEvents }) => {
    const label = dates.format(dayDate, "EEE dd/MM");
    if (dayEvents.length === 0) {
      return `${label}\n• nothing scheduled`;
    }
    const lines = dayEvents.map((e) => {
      const time = dates.format(e.start, "HH:mm");
      return `• ${time} ${e.title}`;
    });
    return `${label}\n${lines.join("\n")}`;
  });

  const text = `Your week ahead:\n\n${blocks.join("\n\n")}`;

  log(`Sending weekly agenda covering ${start} to ${end} with ${events.length} events`);
  await telegram.send({ text });
}

async function run() {
  const emails = await gmail.search({
    days: 14,
    max: 20,
    query: 'tracking OR rastreio OR "código de rastreamento" OR shipped OR enviado'
  });

  // Match common carrier tracking code formats (e.g. UPU S10: 2 letters + 9 digits + 2 letters)
  const codeRegex = /\b[A-Z]{2}\d{9}[A-Z]{2}\b/g;

  const seen = new Set();
  const packages = [];
  for (const email of emails) {
    const text = (email.subject || '') + ' ' + (email.snippet || '');
    const matches = text.match(codeRegex);
    if (!matches) continue;
    for (const code of matches) {
      if (seen.has(code)) continue;
      seen.add(code);
      packages.push({ code: code, email: email });
    }
  }

  if (packages.length === 0) {
    log('No shipping tracking codes found in the last 14 days.');
    return;
  }

  const lines = [];
  for (const pkg of packages) {
    const url = 'https://api.trackingmore.example/v1/track?code=' + encodeURIComponent(pkg.code);
    let info;
    try {
      info = await http.getJSON(url);
    } catch (e) {
      log('Failed to look up ' + pkg.code + ': ' + e);
      continue;
    }
    if (!info) continue;
    const statusText = (info.status || 'unknown status').split('_').join(' ');
    let line = '• ' + pkg.code + ' (' + pkg.email.from_name + ' — ' + pkg.email.subject + '): ' + statusText;
    if (info.last_event) line += ' — ' + info.last_event;
    if (info.eta) line += ', ETA ' + info.eta;
    lines.push(line);
  }

  if (lines.length === 0) {
    log('Tracking codes found but no status could be retrieved.');
    return;
  }

  const message = '📦 Package status\n\n' + lines.join('\n');
  await telegram.send({ text: message });
}

async function run() {
  const tomorrowStart = dates.startOfDay(now(), 1);
  const tomorrowEnd = dates.addDays(tomorrowStart, 1);

  const events = await calendar.events({ from: tomorrowStart, to: tomorrowEnd });

  const meetings = events
    .filter(e => Array.isArray(e.attendees) && e.attendees.length > 0)
    .sort((a, b) => (dates.isBefore(a.start, b.start) ? -1 : 1));

  if (meetings.length === 0) {
    log("Nenhuma reunião de amanhã com convidados.");
    return;
  }

  const blocks = [];
  for (const meeting of meetings) {
    const time = dates.format(meeting.start, "HH:mm");
    const lines = [`${time} ${meeting.title}`];
    for (const attendee of meeting.attendees) {
      const emails = await gmail.search({ query: `from:${attendee}`, days: 14, max: 5 });
      for (const email of emails) {
        const name = email.from_name || email.from;
        const repliedNote = email.replied ? "" : " (sem resposta)";
        lines.push(`• ${name} — "${email.subject}": ${email.snippet}${repliedNote}`);
      }
    }
    blocks.push(lines.join("\n"));
  }

  const dateLabel = dates.format(tomorrowStart, "dd/MM");
  const text = `Preparação para amanhã (${dateLabel})\n\n${blocks.join("\n\n")}`;

  await telegram.send({ text });
}

async function run() {
  const threshold = 5.40;
  const data = await http.getJSON("https://api.exchangerate.example/v1/latest?base=USD&symbols=BRL");
  const rate = data && data.rates && data.rates.BRL;

  if (typeof rate !== "number") {
    log("No USD->BRL rate found in response");
    return;
  }

  log("USD->BRL rate: " + rate);

  if (rate > threshold) {
    const text = "💵 USD→BRL is at " + rate.toFixed(2) + ", above your " + threshold.toFixed(2) + " threshold.";
    await telegram.send({ text: text });
  } else {
    log("Rate is at or below threshold, no alert sent.");
  }
}

async function run() {
  const emails = await gmail.search({ query: "in:inbox -from:me", days: 30, max: 50 });
  const currentTime = now();

  // Keep only emails that haven't been replied to and are older than 3 days
  const candidates = emails.filter(e => {
    if (e.replied) return false;
    if (dates.diffDays(e.date, currentTime) <= 3) return false;
    return true;
  });

  const waiting = [];
  for (const e of candidates) {
    const { p } = await judge.needs_reply(e);
    if (p >= 0.5) waiting.push(e);
  }

  if (waiting.length === 0) {
    log("No emails waiting on a reply for more than 3 days.");
    return;
  }

  waiting.sort((a, b) => (dates.isBefore(a.date, b.date) ? -1 : 1));

  const lines = waiting.map(e => {
    const since = dates.format(e.date, "MMM d");
    return `• ${e.from_name} — "${e.subject}" (since ${since})`;
  });

  const text = `Waiting on your reply (3+ days):\n\n${lines.join("\n")}`;
  await telegram.send({ text });
}

async function run() {
  const startToday = dates.today();
  const startTomorrow = dates.addDays(startToday, 1);
  const from = startToday;
  const to = dates.addDays(startToday, 2);

  const events = await calendar.events({ from, to });
  const birthdays = events.filter(e => e.calendar === "Birthdays");

  const prefix = "Aniversário de ";
  const todayList = [];
  const tomorrowList = [];

  for (const e of birthdays) {
    let name = e.title;
    if (name.startsWith(prefix)) name = name.slice(prefix.length);
    if (dates.sameDay(e.start, startToday)) {
      todayList.push(name);
    } else if (dates.sameDay(e.start, startTomorrow)) {
      tomorrowList.push(name);
    }
  }

  if (todayList.length === 0 && tomorrowList.length === 0) {
    log("Nenhum aniversário hoje ou amanhã, nada a enviar.");
    return;
  }

  const todayStr = dates.format(startToday, "dd/MM");
  const tomorrowStr = dates.format(startTomorrow, "dd/MM");

  let text = "🎂 Aniversários\n\n";
  text += `Hoje (${todayStr}): ${todayList.length > 0 ? todayList.join(", ") : "Nenhum"}\n`;
  text += `Amanhã (${tomorrowStr}): ${tomorrowList.length > 0 ? tomorrowList.join(", ") : "Nenhum"}`;

  await telegram.send({ text });
}
